export const envelope = [56, 52, 56];

function catmullRom(p0, p1, p2, p3, u) {
  return 0.5 * (
    (2 * p1) +
    (-p0 + p2) * u +
    (2 * p0 - 5 * p1 + 4 * p2 - p3) * u * u +
    (-p0 + 3 * p1 - 3 * p2 + p3) * u * u * u
  );
}

function evalSpline(points, t) {
  const n = points.length - 1;
  const p = Math.max(0, Math.min(n, t * n));
  const i = Math.min(Math.floor(p), n - 1);
  const frac = p - i;

  const p0 = points[Math.max(0, i - 1)];
  const p1 = points[i];
  const p2 = points[Math.min(n, i + 1)];
  const p3 = points[Math.min(n, i + 2)];

  return [
    catmullRom(p0[0], p1[0], p2[0], p3[0], frac),
    catmullRom(p0[1], p1[1], p2[1], p3[1], frac),
    catmullRom(p0[2], p1[2], p2[2], p3[2], frac)
  ];
}

export default function build(api) {
  const W = 56;
  const H = 52;
  const D = 56;
  const grid = new Uint8Array(W * H * D);

  function idx(x, y, z) {
    return x + 56 * (y + 52 * z);
  }

  function setVoxel(x, y, z, id) {
    const ix = Math.round(x);
    const iy = Math.round(y);
    const iz = Math.round(z);
    if (ix >= 0 && ix < W && iy >= 0 && iy < H && iz >= 0 && iz < D) {
      grid[idx(ix, iy, iz)] = id;
    }
  }

  function getVoxel(x, y, z) {
    const ix = Math.round(x);
    const iy = Math.round(y);
    const iz = Math.round(z);
    if (ix >= 0 && ix < W && iy >= 0 && iy < H && iz >= 0 && iz < D) {
      return grid[idx(ix, iy, iz)];
    }
    return 0;
  }

  // =========================================================================
  // 1. Hellenist Urban Promenade & Breached Quay (z: 0 to 16)
  // =========================================================================
  const breachMinX = 17;
  const breachMaxX = 39;

  for (let x = 0; x < W; x++) {
    for (let z = 0; z <= 15; z++) {
      const isBreach = (x >= breachMinX && x <= breachMaxX && z >= 11);
      const isCrater = (x >= 4 && x <= 10 && z >= 2 && z <= 8);

      if (isBreach) {
        const distBreach = Math.min(x - breachMinX, breachMaxX - x);
        const breachH = Math.max(0, Math.min(2, Math.floor(distBreach / 3)));
        for (let y = 0; y <= breachH; y++) {
          setVoxel(x, y, z, (x + y + z) % 3 === 0 ? 16 : 13);
        }
      } else if (isCrater) {
        const cdx = x - 7;
        const cdz = z - 5;
        const cr = Math.sqrt(cdx * cdx + cdz * cdz);
        const deckH = cr < 2.2 ? 1 : (cr < 3.5 ? 2 : 3);
        for (let y = 0; y <= deckH; y++) {
          if (y === deckH && cr < 2.5) {
            setVoxel(x, y, z, 5);
          } else if (y === deckH) {
            setVoxel(x, y, z, 16);
          } else {
            setVoxel(x, y, z, 12);
          }
        }
      } else {
        for (let y = 0; y <= 3; y++) {
          if (y === 3) {
            setVoxel(x, y, z, (x * 7 + z * 13) % 11 === 0 ? 16 : 15);
          } else {
            setVoxel(x, y, z, 12);
          }
        }
        if (z === 13 && (x < breachMinX - 1 || x > breachMaxX + 1)) {
          setVoxel(x, 4, z, 13);
        }
      }
    }
  }

  // Classical Colonnade
  function buildColumn(baseX, baseZ, maxH, isGripped) {
    for (let y = 4; y < 4 + maxH; y++) {
      if (y === 4) {
        setVoxel(baseX, y, baseZ, 13);
        setVoxel(baseX + 1, y, baseZ, 13);
        setVoxel(baseX, y, baseZ + 1, 13);
        setVoxel(baseX + 1, y, baseZ + 1, 13);
      } else if (y === 4 + maxH - 1 && !isGripped) {
        setVoxel(baseX, y, baseZ, 12);
        setVoxel(baseX + 1, y, baseZ, 12);
      } else {
        setVoxel(baseX, y, baseZ, 14);
        setVoxel(baseX + 1, y, baseZ, 14);
        setVoxel(baseX, y, baseZ + 1, 14);
        setVoxel(baseX + 1, y, baseZ + 1, 14);
      }
    }
  }

  buildColumn(12, 6, 4, false);
  setVoxel(15, 4, 7, 14);
  setVoxel(16, 4, 7, 14);
  setVoxel(17, 4, 8, 14);
  setVoxel(18, 4, 8, 12);

  buildColumn(20, 6, 2, false);
  setVoxel(22, 4, 6, 16);
  setVoxel(23, 4, 7, 14);

  buildColumn(34, 6, 3, false);
  setVoxel(33, 4, 8, 14);
  setVoxel(32, 4, 9, 16);

  buildColumn(44, 6, 10, true);

  // =========================================================================
  // 2. Churning Ocean Bay Foam & Seabed Base (z: 14 to 55, y: 0 to 3)
  // =========================================================================
  for (let x = 0; x < W; x++) {
    for (let z = 14; z < D; z++) {
      const dx = (x - 28) / 19.0;
      const dz = (z - 34) / 17.0;
      const dist = Math.sqrt(dx * dx + dz * dz);

      if (dist <= 1.25) {
        setVoxel(x, 0, z, 1);
        setVoxel(x, 1, z, dist < 0.9 ? 1 : 3);
        if (dist > 0.6 && dist < 1.15) {
          const foamNoise = (x * 13 + z * 29) % 7;
          if (foamNoise > 2) setVoxel(x, 2, z, 11);
          if (foamNoise === 6) setVoxel(x, 2, z, 4);
        }
      } else if (dist <= 1.45) {
        setVoxel(x, 0, z, 1);
        if ((x + z) % 3 === 0) setVoxel(x, 1, z, 11);
      } else {
        setVoxel(x, 0, z, 1);
      }
    }
  }

  // =========================================================================
  // 3. Leviathan Main Torso, Neck & Spine
  // =========================================================================
  const spinePoints = [
    [28, 0, 44],
    [28, 6, 39],
    [28, 14, 34],
    [28, 23, 29],
    [28, 31, 24],
    [28, 38, 18],
    [28, 41, 13],
    [28, 41, 7]
  ];

  const spineSteps = 90;
  for (let s = 0; s <= spineSteps; s++) {
    const t = s / spineSteps;
    const pt = evalSpline(spinePoints, t);
    const px = pt[0], py = pt[1], pz = pt[2];

    let rx = 6.0, ry = 6.0, rz = 6.0;
    if (t < 0.25) {
      const u = t / 0.25;
      rx = 6.5 + u * 2.0;
      ry = 5.5 + u * 2.5;
      rz = 6.0 + u * 2.0;
    } else if (t < 0.65) {
      const u = (t - 0.25) / 0.40;
      rx = 8.5 - u * 2.0;
      ry = 8.0 - u * 2.0;
      rz = 8.0 - u * 2.0;
    } else if (t < 0.85) {
      const u = (t - 0.65) / 0.20;
      rx = 6.5 - u * 1.5;
      ry = 6.0 - u * 1.2;
      rz = 6.0 - u * 1.2;
    } else {
      const u = (t - 0.85) / 0.15;
      rx = 5.0 - u * 1.8;
      ry = 4.8 - u * 2.0;
      rz = 4.8 - u * 2.0;
    }

    const minX = Math.floor(px - rx), maxX = Math.ceil(px + rx);
    const minY = Math.floor(py - ry), maxY = Math.ceil(py + ry);
    const minZ = Math.floor(pz - rz), maxZ = Math.ceil(pz + rz);

    for (let x = minX; x <= maxX; x++) {
      for (let y = minY; y <= maxY; y++) {
        for (let z = minZ; z <= maxZ; z++) {
          const dx = (x - px) / rx;
          const dy = (y - py) / ry;
          const dz = (z - pz) / rz;
          const d2 = dx * dx + dy * dy + dz * dz;

          if (d2 <= 1.0) {
            const distSurf = 1.0 - Math.sqrt(d2);
            let blockId = 1;

            if (distSurf > 0.35) {
              blockId = (y + z) % 2 === 0 ? 6 : 7;
            } else if (dy < -0.35) {
              if (Math.floor(t * 16) % 2 === 0 && dy < -0.55) {
                blockId = (x + z) % 2 === 0 ? 4 : 9;
              } else {
                blockId = 3;
              }
            } else if (dy > 0.35) {
              blockId = (distSurf < 0.12 && ((x + y + z) % 3 === 0)) ? 5 : 1;
            } else {
              blockId = (x + y + z) % 2 === 0 ? 2 : 1;
            }

            setVoxel(x, y, z, blockId);
          }
        }
      }
    }
  }

  // =========================================================================
  // 4. Ribbed Carapace Armor Plates & Dorsal Horn Spikes
  // =========================================================================
  const ribCount = 7;
  for (let r = 0; r < ribCount; r++) {
    const ribT = 0.18 + r * 0.08;
    const rpt = evalSpline(spinePoints, ribT);
    const rpx = rpt[0], rpy = rpt[1], rpz = rpt[2];

    const spikeH = 4 + (r % 3 === 1 ? 3 : 1);
    for (let sh = 0; sh <= spikeH; sh++) {
      const sy = Math.round(rpy + 6.5 + sh);
      const sz = Math.round(rpz - sh * 0.4);
      if (sh === spikeH) {
        setVoxel(28, sy, sz, 8);
      } else if (sh > spikeH - 2) {
        setVoxel(28, sy, sz, 8);
        setVoxel(27, sy, sz, 1);
        setVoxel(29, sy, sz, 1);
      } else {
        setVoxel(28, sy, sz, 5);
        setVoxel(27, sy, sz, 1);
        setVoxel(29, sy, sz, 1);
      }
    }

    const ribSpan = 8.5 + (r < 4 ? r * 0.5 : (6 - r) * 0.5);
    for (let angle = 0; angle <= 16; angle++) {
      const theta = (angle / 16) * Math.PI;
      const lx = 28 - Math.sin(theta) * ribSpan;
      const rx = 28 + Math.sin(theta) * ribSpan;
      const ry = rpy + Math.cos(theta) * (ribSpan * 0.75);
      const rz = rpz + Math.sin(theta) * 1.5;

      const ribId = (angle === 8 || angle === 9) ? 8 : (angle % 3 === 0 ? 5 : 1);
      setVoxel(lx, ry, rz, ribId);
      setVoxel(rx, ry, rz, ribId);
      setVoxel(lx, ry - 1, rz, 1);
      setVoxel(rx, ry - 1, rz, 1);
    }
  }

  // =========================================================================
  // 5. Head, Crown Crest, Jaws & Bioluminescent Eyes
  // =========================================================================
  const hx = 28, hy = 41, hz = 13;

  for (let x = hx - 6; x <= hx + 6; x++) {
    for (let y = hy - 4; y <= hy + 7; y++) {
      for (let z = hz - 7; z <= hz + 6; z++) {
        const dx = (x - hx) / 5.5;
        const dy = (y - hy) / 5.0;
        const dz = (z - hz) / 6.0;
        const d = dx * dx + dy * dy + dz * dz;

        if (d <= 1.0) {
          if (y >= hy + 2 && dz > -0.2) {
            setVoxel(x, y, z, (x + z) % 3 === 0 ? 5 : 1);
          } else if (y >= hy - 1) {
            setVoxel(x, y, z, 1);
          }
        }
      }
    }
  }

  // Mouth cavity & throat
  for (let x = hx - 3; x <= hx + 3; x++) {
    for (let y = hy - 3; y <= hy + 1; y++) {
      for (let z = hz - 6; z <= hz + 3; z++) {
        if (z >= hz + 1) {
          setVoxel(x, y, z, (x === hx && y === hy - 1) ? 10 : 4);
        } else {
          setVoxel(x, y, z, 0);
        }
      }
    }
  }

  // Teeth & Fangs
  for (let x = hx - 3; x <= hx + 3; x++) {
    for (let z = hz - 6; z <= hz - 1; z++) {
      if (Math.abs(x - hx) === 3 || z === hz - 6) {
        setVoxel(x, hy, z, 8);
      }
    }
  }
  setVoxel(hx - 3, hy - 1, hz - 5, 8);
  setVoxel(hx - 3, hy - 2, hz - 5, 11);
  setVoxel(hx + 3, hy - 1, hz - 5, 8);
  setVoxel(hx + 3, hy - 2, hz - 5, 11);

  // Lower Jaw
  for (let z = hz - 6; z <= hz + 2; z++) {
    const tJaw = (z - (hz - 6)) / 8.0;
    const jy = Math.round(hy - 5 + tJaw * 1.5);
    const jw = Math.round(3.5 - tJaw * 0.5);

    for (let x = hx - jw; x <= hx + jw; x++) {
      setVoxel(x, jy, z, 1);
      setVoxel(x, jy + 1, z, 1);
      if (Math.abs(x - hx) === jw || z === hz - 6) {
        setVoxel(x, jy + 2, z, 8);
      }
    }
  }
  setVoxel(hx - 2, hy - 2, hz - 6, 8);
  setVoxel(hx - 2, hy - 1, hz - 6, 11);
  setVoxel(hx + 2, hy - 2, hz - 6, 8);
  setVoxel(hx + 2, hy - 1, hz - 6, 11);

  // Eyes
  setVoxel(hx - 4, hy + 2, hz - 3, 9);
  setVoxel(hx - 4, hy + 2, hz - 2, 4);
  setVoxel(hx - 5, hy + 2, hz - 3, 5);
  setVoxel(hx - 4, hy + 3, hz - 3, 5);
  setVoxel(hx - 4, hy + 1, hz - 3, 5);

  setVoxel(hx + 4, hy + 2, hz - 3, 9);
  setVoxel(hx + 4, hy + 2, hz - 2, 4);
  setVoxel(hx + 5, hy + 2, hz - 3, 5);
  setVoxel(hx + 4, hy + 3, hz - 3, 5);
  setVoxel(hx + 4, hy + 1, hz - 3, 5);

  setVoxel(hx - 4, hy + 4, hz - 1, 10);
  setVoxel(hx + 4, hy + 4, hz - 1, 10);

  // Horns
  const horns = [
    [[28, 46, 15], [28, 49, 19], [28, 51, 24]],
    [[25, 45, 15], [21, 48, 20], [17, 50, 25]],
    [[31, 45, 15], [35, 48, 20], [39, 50, 25]],
    [[23, 43, 17], [18, 45, 22], [14, 46, 27]],
    [[33, 43, 17], [38, 45, 22], [42, 46, 27]]
  ];

  for (let hIdx = 0; hIdx < horns.length; hIdx++) {
    const hornPts = horns[hIdx];
    const steps = 25;
    for (let s = 0; s <= steps; s++) {
      const ht = s / steps;
      const hpt = evalSpline(hornPts, ht);
      const hRad = (1.0 - ht) * 1.6 + 0.5;

      const minKx = Math.floor(hpt[0] - hRad), maxKx = Math.ceil(hpt[0] + hRad);
      const minKy = Math.floor(hpt[1] - hRad), maxKy = Math.ceil(hpt[1] + hRad);
      const minKz = Math.floor(hpt[2] - hRad), maxKz = Math.ceil(hpt[2] + hRad);

      for (let kx = minKx; kx <= maxKx; kx++) {
        for (let ky = minKy; ky <= maxKy; ky++) {
          for (let kz = minKz; kz <= maxKz; kz++) {
            const d = (kx - hpt[0]) * (kx - hpt[0]) + (ky - hpt[1]) * (ky - hpt[1]) + (kz - hpt[2]) * (kz - hpt[2]);
            if (d <= hRad * hRad) {
              if (ht > 0.8) {
                setVoxel(kx, ky, kz, 8);
              } else if (ht > 0.4) {
                setVoxel(kx, ky, kz, (kx + ky + kz) % 2 === 0 ? 5 : 1);
              } else {
                setVoxel(kx, ky, kz, 1);
              }
            }
          }
        }
      }
    }
  }

  // =========================================================================
  // 6. Writhing Kraken Tentacles
  // =========================================================================
  const tentacles = [
    {
      pts: [
        [21, 8, 28], [15, 17, 23], [8, 25, 17], [4, 18, 10],
        [5, 8, 5], [7, 2, 4], [10, 5, 2], [12, 9, 3]
      ],
      r0: 3.8, r1: 1.1,
      suckerDir: [0.5, -0.6, -0.5]
    },
    {
      pts: [
        [35, 8, 28], [41, 17, 23], [47, 26, 17], [50, 19, 10],
        [48, 8, 6], [44, 3, 5], [40, 7, 7], [43, 12, 7]
      ],
      r0: 3.8, r1: 1.1,
      suckerDir: [-0.5, -0.6, -0.5]
    },
    {
      pts: [
        [19, 6, 36], [11, 15, 34], [5, 24, 28], [4, 32, 20],
        [7, 36, 13], [12, 34, 8], [16, 29, 6]
      ],
      r0: 3.5, r1: 1.0,
      suckerDir: [0.6, -0.4, 0.4]
    },
    {
      pts: [
        [37, 6, 36], [45, 16, 36], [51, 27, 30], [51, 38, 24],
        [46, 45, 20], [39, 46, 18], [34, 42, 19]
      ],
      r0: 3.5, r1: 1.0,
      suckerDir: [-0.6, -0.4, 0.4]
    },
    {
      pts: [
        [23, 3, 44], [15, 11, 48], [8, 19, 50],
        [4, 26, 45], [5, 31, 38], [9, 32, 33]
      ],
      r0: 3.2, r1: 0.9,
      suckerDir: [0.5, 0.3, -0.6]
    },
    {
      pts: [
        [33, 3, 44], [41, 11, 48], [48, 19, 50],
        [52, 26, 45], [51, 31, 38], [47, 32, 33]
      ],
      r0: 3.2, r1: 0.9,
      suckerDir: [-0.5, 0.3, -0.6]
    }
  ];

  for (let tIdx = 0; tIdx < tentacles.length; tIdx++) {
    const tent = tentacles[tIdx];
    const steps = 60;
    const sx = tent.suckerDir[0];
    const sy = tent.suckerDir[1];
    const sz = tent.suckerDir[2];
    const sLen = Math.sqrt(sx * sx + sy * sy + sz * sz) || 1;
    const nsx = sx / sLen, nsy = sy / sLen, nsz = sz / sLen;

    for (let s = 0; s <= steps; s++) {
      const t = s / steps;
      const pt = evalSpline(tent.pts, t);
      const rad = tent.r0 * (1.0 - t) + tent.r1 * t;

      const minX = Math.floor(pt[0] - rad), maxX = Math.ceil(pt[0] + rad);
      const minY = Math.floor(pt[1] - rad), maxY = Math.ceil(pt[1] + rad);
      const minZ = Math.floor(pt[2] - rad), maxZ = Math.ceil(pt[2] + rad);

      for (let x = minX; x <= maxX; x++) {
        for (let y = minY; y <= maxY; y++) {
          for (let z = minZ; z <= maxZ; z++) {
            const vx = x - pt[0], vy = y - pt[1], vz = z - pt[2];
            const dist = Math.sqrt(vx * vx + vy * vy + vz * vz);

            if (dist <= rad) {
              const distSurf = rad - dist;
              let tBlock = 1;

              if (distSurf > 0.45) {
                tBlock = 7;
              } else {
                const nvx = vx / (dist || 1), nvy = vy / (dist || 1), nvz = vz / (dist || 1);
                const dotSucker = nvx * nsx + nvy * nsy + nvz * nsz;

                if (dotSucker > 0.38) {
                  if (Math.floor(t * 36) % 2 === 0 && dotSucker > 0.60) {
                    tBlock = 4;
                  } else {
                    tBlock = 1;
                  }
                } else {
                  tBlock = (x + y + z) % 2 === 0 ? 2 : 1;
                }
              }

              const cur = getVoxel(x, y, z);
              if (cur !== 14 && cur !== 12) {
                setVoxel(x, y, z, tBlock);
              }
            }
          }
        }
      }
    }
  }

  // =========================================================================
  // 7. Ensure Single 6-Connected Solid Component
  // =========================================================================
  const visited = new Uint8Array(W * H * D);
  let seed = -1;

  for (let dy = 0; dy <= 25; dy++) {
    for (let r = 0; r < 20; r++) {
      for (let dx = -r; dx <= r; dx++) {
        for (let dz = -r; dz <= r; dz++) {
          const x = 28 + dx, y = 10 + dy, z = 30 + dz;
          if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
            const i = idx(x, y, z);
            if (grid[i] !== 0) {
              seed = i;
              break;
            }
          }
        }
        if (seed !== -1) break;
      }
      if (seed !== -1) break;
    }
    if (seed !== -1) break;
  }

  if (seed !== -1) {
    const queue = new Int32Array(W * H * D);
    let head = 0, tail = 0;
    queue[tail++] = seed;
    visited[seed] = 1;

    const dxs = [1, -1, 0, 0, 0, 0];
    const dys = [0, 0, 1, -1, 0, 0];
    const dzs = [0, 0, 0, 0, 1, -1];

    while (head < tail) {
      const cur = queue[head++];
      const cz = Math.floor(cur / (56 * 52));
      const rem = cur % (56 * 52);
      const cy = Math.floor(rem / 56);
      const cx = rem % 56;

      for (let d = 0; d < 6; d++) {
        const nx = cx + dxs[d];
        const ny = cy + dys[d];
        const nz = cz + dzs[d];
        if (nx >= 0 && nx < W && ny >= 0 && ny < H && nz >= 0 && nz < D) {
          const ni = idx(nx, ny, nz);
          if (!visited[ni] && grid[ni] !== 0) {
            visited[ni] = 1;
            queue[tail++] = ni;
          }
        }
      }
    }

    for (let i = 0; i < W * H * D; i++) {
      if (grid[i] !== 0 && !visited[i]) {
        grid[i] = 0;
      }
    }
  }

  // =========================================================================
  // 8. Palette Mapping & Emission
  // =========================================================================
  const themeStonePrim = (api.theme && api.theme.stone && api.theme.stone.primary) || "minecraft:smooth_quartz";
  const themeStoneAcc = (api.theme && api.theme.stone && api.theme.stone.accent) || "minecraft:stone_bricks";
  const themePavement = (api.theme && api.theme.ground && api.theme.ground.pavement) || "minecraft:polished_andesite";

  function resolveBlock(id) {
    if (id === 1) return "minecraft:dark_prismarine";
    if (id === 2) return "minecraft:prismarine_bricks";
    if (id === 3) return "minecraft:prismarine";
    if (id === 4) return "minecraft:sea_lantern";
    if (id === 5) return "minecraft:crying_obsidian";
    if (id === 6) return "minecraft:warped_wart_block";
    if (id === 7) return "minecraft:cyan_terracotta";
    if (id === 8) return "minecraft:bone_block";
    if (id === 9) return "minecraft:verdant_froglight";
    if (id === 10) return "minecraft:pearlescent_froglight";
    if (id === 11) return "minecraft:calcite";
    if (id === 12) return themeStonePrim;
    if (id === 13) return themeStoneAcc;
    if (id === 14) return "minecraft:quartz_pillar[axis=y]";
    if (id === 15) return themePavement;
    if (id === 16) return "minecraft:cracked_stone_bricks";
    return null;
  }

  for (let x = 0; x < W; x++) {
    for (let y = 0; y < H; y++) {
      for (let z = 0; z < D; z++) {
        const id = grid[idx(x, y, z)];
        if (id !== 0) {
          const blockStr = resolveBlock(id);
          if (blockStr) {
            api.set(x, y, z, blockStr);
          }
        }
      }
    }
  }

  return {
    name: "colossal_leviathan",
    seatY: 0,
    anchors: {
      front: [28, 4, 0],
      maw: [28, 41, 7],
      crest: [28, 51, 24]
    }
  };
}

guardian_colossus.source:
export const envelope = [25, 52, 25];

export default function build(api) {
  const [W, H, D] = api.size;

  // --- Palette Resolution (Theme-Driven with Sci-Fi / Hellenic Materials) ---
  const pStone = api.theme?.stone?.primary || "minecraft:smooth_quartz";
  const aStone = api.theme?.stone?.accent || "minecraft:quartz_bricks";
  const stWall = api.theme?.stone?.wall || "minecraft:diorite_wall";
  const gPlinth = api.theme?.ground?.plinth || "minecraft:polished_andesite";
  const gPavement = api.theme?.ground?.pavement || "minecraft:smooth_stone";

  // Specialized Guardian Colossus Materials
  const bTitanium = "minecraft:iron_block";
  const bGold = "minecraft:gold_block";
  const bRawGold = "minecraft:raw_gold_block";
  const bEnergy = "minecraft:sea_lantern";
  const bGlass = "minecraft:cyan_stained_glass";
  const bPrismarine = "minecraft:dark_prismarine";
  const bPillar = "minecraft:quartz_pillar[axis=y]";
  const bSmoothQuartz = "minecraft:smooth_quartz";
  const bIronBars = "minecraft:iron_bars";
  const bRod = "minecraft:lightning_rod[facing=north]";
  const bEndRod = "minecraft:end_rod[facing=north]";

  const stoneStairBase = (api.theme?.stone?.stairs || "minecraft:quartz_stairs").split("[")[0];
  const groundStairBase = (api.theme?.ground?.stairs || api.theme?.stone?.stairs || "minecraft:stone_brick_stairs").split("[")[0];

  function getStairs(facing, half = "bottom") {
    const id = stoneStairBase.endsWith("_stairs") ? stoneStairBase : "minecraft:quartz_stairs";
    return `${id}[facing=${facing},half=${half}]`;
  }

  function getGroundStairs(facing, half = "bottom") {
    const id = groundStairBase.endsWith("_stairs") ? groundStairBase : "minecraft:stone_brick_stairs";
    return `${id}[facing=${facing},half=${half}]`;
  }

  function setBlock(x, y, z, block) {
    x = Math.round(x);
    y = Math.round(y);
    z = Math.round(z);
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      api.set(x, y, z, block);
    }
  }

  const seatY = 4;
  const cx = 12;
  const cz = 12;

  // =========================================================================
  // 1. TERRAIN INTEGRATION & FOUNDATION SKIRT (y = 0..3)
  // =========================================================================
  for (let x = 1; x <= 23; x++) {
    for (let z = 1; z <= 23; z++) {
      const h = api.heightAt(x, z);
      const groundY = Math.max(0, Math.min(seatY, seatY + Math.floor(h)));
      for (let y = groundY; y < seatY; y++) {
        setBlock(x, y, z, gPlinth);
      }
    }
  }

  // =========================================================================
  // 2. GRAND STEPPED PLINTH BASE (y = 4..6)
  // =========================================================================
  // Tier 1: Stylobate Lower Deck (y = 4, 23x23)
  for (let x = 1; x <= 23; x++) {
    for (let z = 1; z <= 23; z++) {
      if (x === 1 && z === 1) setBlock(x, 4, z, gPlinth);
      else if (x === 23 && z === 1) setBlock(x, 4, z, gPlinth);
      else if (x === 1 && z === 23) setBlock(x, 4, z, gPlinth);
      else if (x === 23 && z === 23) setBlock(x, 4, z, gPlinth);
      else if (z === 1) setBlock(x, 4, z, getGroundStairs("north"));
      else if (z === 23) setBlock(x, 4, z, getGroundStairs("south"));
      else if (x === 1) setBlock(x, 4, z, getGroundStairs("west"));
      else if (x === 23) setBlock(x, 4, z, getGroundStairs("east"));
      else setBlock(x, 4, z, gPavement);
    }
  }

  // Tier 2: Middle Step (y = 5, 21x21)
  for (let x = 2; x <= 22; x++) {
    for (let z = 2; z <= 22; z++) {
      if (x === 2 && z === 2) setBlock(x, 5, z, aStone);
      else if (x === 22 && z === 2) setBlock(x, 5, z, aStone);
      else if (x === 2 && z === 22) setBlock(x, 5, z, aStone);
      else if (x === 22 && z === 22) setBlock(x, 5, z, aStone);
      else if (z === 2) setBlock(x, 5, z, getStairs("north"));
      else if (z === 22) setBlock(x, 5, z, getStairs("south"));
      else if (x === 2) setBlock(x, 5, z, getStairs("west"));
      else if (x === 22) setBlock(x, 5, z, getStairs("east"));
      else setBlock(x, 5, z, pStone);
    }
  }

  // Tier 3: Podium Platform (y = 6, 19x19)
  for (let x = 3; x <= 21; x++) {
    for (let z = 3; z <= 21; z++) {
      if (x === 3 || x === 21 || z === 3 || z === 21) {
        setBlock(x, 6, z, aStone);
      } else {
        setBlock(x, 6, z, pStone);
      }
    }
  }

  // Front Entrance Staircase (North, z = 0..2)
  for (let x = 10; x <= 14; x++) {
    setBlock(x, 4, 0, getGroundStairs("north"));
    setBlock(x, 5, 1, getStairs("north"));
    setBlock(x, 6, 2, getStairs("north"));
  }
  // Flanking Beacon Pylons at the base steps
  for (let y = 4; y <= 7; y++) {
    setBlock(9, y, 1, aStone);
    setBlock(15, y, 1, aStone);
  }
  setBlock(9, 8, 1, bEnergy);
  setBlock(15, 8, 1, bEnergy);
  setBlock(9, 9, 1, bRod);
  setBlock(15, 9, 1, bRod);

  // =========================================================================
  // 3. NEOCLASSICAL PEDESTAL & INTERIOR SANCTUM (y = 6..12)
  // =========================================================================
  // Exterior walls & pilasters: x: 5..19, z: 5..19
  for (let y = 6; y <= 11; y++) {
    for (let x = 5; x <= 19; x++) {
      for (let z = 5; z <= 19; z++) {
        const isCornerPier =
          (x <= 6 || x >= 18) && (z <= 6 || z >= 18);
        const isWall = (x === 5 || x === 19 || z === 5 || z === 19);

        if (isCornerPier) {
          if (y === 6 || y === 11) setBlock(x, y, z, aStone);
          else setBlock(x, y, z, bPillar);
        } else if (isWall) {
          // North facade entrance opening
          if (z === 5 && x >= 11 && x <= 13 && y <= 9) {
            // Hollow for portal entrance
            continue;
          }

          // Fluted pilasters and energy accents
          if (x === 12 || z === 12 || x === 10 || x === 14) {
            setBlock(x, y, z, bPillar);
          } else if (y === 8 || y === 9) {
            setBlock(x, y, z, bTitanium);
          } else {
            setBlock(x, y, z, pStone);
          }
        }
      }
    }
  }

  // Entrance Portal Arch & Entablature (North, z = 5)
  setBlock(10, 10, 4, getStairs("east"));
  setBlock(14, 10, 4, getStairs("west"));
  setBlock(11, 10, 4, aStone);
  setBlock(12, 10, 4, bEnergy);
  setBlock(13, 10, 4, aStone);
  setBlock(12, 11, 4, bGold);

  // Pedestal Chamber Floor Inlay Mosaic (y = 4, inside chamber)
  for (let x = 7; x <= 17; x++) {
    for (let z = 7; z <= 17; z++) {
      const d = Math.hypot(x - cx, z - cz);
      if (d <= 1.5) setBlock(x, 4, z, bGold);
      else if (d <= 3.5) setBlock(x, 4, z, bPrismarine);
      else setBlock(x, 4, z, gPavement);
    }
  }

  // Interior Chamber Corner Columns (y = 5..10)
  for (let y = 5; y <= 10; y++) {
    setBlock(7, y, 7, bPillar);
    setBlock(17, y, 7, bPillar);
    setBlock(7, y, 17, bPillar);
    setBlock(17, y, 17, bPillar);
  }

  // Pedestal Cornice & Overhanging Frieze (y = 11..12)
  for (let x = 4; x <= 20; x++) {
    for (let z = 4; z <= 20; z++) {
      // Ceiling slab over inner room
      if (x >= 6 && x <= 18 && z >= 6 && z <= 18) {
        setBlock(x, 11, z, aStone);
        setBlock(x, 12, z, gPavement);
      }
      // Frieze band at y = 11
      if (x === 5 || x === 19 || z === 5 || z === 19) {
        if ((x + z) % 2 === 0) setBlock(x, 11, z, bGold);
      }
      // Cornice perimeter overhang at y = 12
      if (x === 4 || x === 20 || z === 4 || z === 20) {
        if (z === 4) setBlock(x, 12, z, getStairs("north", "top"));
        else if (z === 20) setBlock(x, 12, z, getStairs("south", "top"));
        else if (x === 4) setBlock(x, 12, z, getStairs("west", "top"));
        else if (x === 20) setBlock(x, 12, z, getStairs("east", "top"));
      }
      // Parapet balustrade at y = 13
      if (x === 4 || x === 20 || z === 4 || z === 20) {
        if ((x + z) % 3 === 0) setBlock(x, 13, z, stWall);
        else setBlock(x, 13, z, bIronBars);
      }
    }
  }

  // =========================================================================
  // 4. COLOSSUS PODIUM SOCLE (y = 13..14)
  // =========================================================================
  for (let dx = -5; dx <= 5; dx++) {
    for (let dz = -5; dz <= 5; dz++) {
      const d = Math.hypot(dx, dz);
      if (d <= 4.6) {
        setBlock(cx + dx, 13, cz + dz, (d > 3.8) ? bGold : aStone);
      }
      if (d <= 3.8) {
        setBlock(cx + dx, 14, cz + dz, (d > 3.0) ? bGold : pStone);
      }
    }
  }
  // Energy conduit lines on socle
  setBlock(cx, 14, cz - 3, bEnergy);
  setBlock(cx, 14, cz + 3, bEnergy);
  setBlock(cx - 3, 14, cz, bEnergy);
  setBlock(cx + 3, 14, cz, bEnergy);

  // =========================================================================
  // 5. COLOSSUS: FEET & LOWER PEPLOS (y = 15..27)
  // =========================================================================
  // Golden strapped sandals
  // Left foot (forward stance): x = 13..15, z = 8..11, y = 15
  for (let x = 13; x <= 15; x++) {
    for (let z = 8; z <= 11; z++) {
      setBlock(x, 15, z, (z === 8 || z === 11) ? bGold : pStone);
    }
  }
  // Right foot (firm load-bearing): x = 9..11, z = 12..15, y = 15
  for (let x = 9; x <= 11; x++) {
    for (let z = 12; z <= 15; z++) {
      setBlock(x, 15, z, (z === 12 || z === 15) ? bGold : pStone);
    }
  }

  // Draped Peplos / Hellenic Robe with Classical Fluting
  for (let y = 15; y <= 27; y++) {
    const t = (y - 15) / 12; // 0 at base, 1 at waist
    const hipBulge = (y >= 23 && y <= 26) ? 0.35 : 0;
    const rx = 4.2 * (1 - t * 0.28) + hipBulge;
    const rz = 3.9 * (1 - t * 0.28) + hipBulge;

    const xCenter = cx + Math.sin(t * Math.PI) * 0.35;
    const zCenter = cz - (1 - t) * 0.3;

    for (let dx = -6; dx <= 6; dx++) {
      for (let dz = -6; dz <= 6; dz++) {
        const x = Math.round(xCenter + dx);
        const z = Math.round(zCenter + dz);
        const angle = Math.atan2(dz, dx);
        const fluting = Math.sin(angle * 7) * 0.38;
        const normDist = Math.hypot(dx / rx, dz / rz);

        if (normDist <= (1.0 + fluting / Math.max(rx, rz))) {
          // Front pleat and titanium conduit piping
          const isFrontPleat = (angle > -2.2 && angle < -0.9);
          if (isFrontPleat && normDist > 0.75) {
            setBlock(x, y, z, (y % 3 === 0) ? bTitanium : bSmoothQuartz);
          } else if (normDist > 0.85 && (angle > 1.2 && angle < 1.9)) {
            setBlock(x, y, z, aStone);
          } else if (normDist <= 0.45 && y % 4 === 0) {
            setBlock(x, y, z, bEnergy);
          } else {
            setBlock(x, y, z, pStone);
          }
        }
      }
    }
  }

  // =========================================================================
  // 6. COLOSSUS: GOLDEN CINCTURE / BELT (y = 27..28)
  // =========================================================================
  for (let y = 27; y <= 28; y++) {
    for (let dx = -4; dx <= 4; dx++) {
      for (let dz = -4; dz <= 4; dz++) {
        const d = Math.hypot(dx / 3.4, dz / 2.9);
        if (d >= 0.75 && d <= 1.15) {
          setBlock(cx + dx, y, cz + dz, bGold);
        } else if (d < 0.75) {
          setBlock(cx + dx, y, cz + dz, bSmoothQuartz);
        }
      }
    }
  }
  // Gorgoneion Medallion Buckle (Front Center, y = 27..28, z = 9)
  setBlock(cx, 27, 9, bEnergy);
  setBlock(cx, 28, 9, bGold);
  setBlock(cx - 1, 27, 9, bRawGold);
  setBlock(cx + 1, 27, 9, bRawGold);

  // =========================================================================
  // 7. COLOSSUS: TORSO & AEGIS CUIRASS (y = 28..36)
  // =========================================================================
  for (let y = 28; y <= 35; y++) {
    const t = (y - 28) / 7;
    const rx = 3.1 + t * 1.9;
    const rz = 2.7 + t * 0.4;

    for (let dx = -6; dx <= 6; dx++) {
      for (let dz = -5; dz <= 5; dz++) {
        const x = cx + dx;
        const z = cz + dz;
        const d = Math.hypot(dx / rx, dz / rz);

        if (d <= 1.0) {
          const diag = (y - 28) + dx * 0.75;
          const isAegis = (dz < 0 && diag >= 1.5 && diag <= 6.5);

          if (isAegis) {
            if (diag <= 2.2 || diag >= 5.8) {
              setBlock(x, y, z, bGold);
            } else {
              setBlock(x, y, z, bTitanium);
            }
          } else {
            setBlock(x, y, z, bSmoothQuartz);
          }
        }
      }
    }
  }

  // Aegis Gorgon EMP Core (Center Chest, y = 32..34, z = 9)
  setBlock(cx, 33, 9, bEnergy);
  setBlock(cx, 32, 9, bPrismarine);
  setBlock(cx, 34, 9, bPrismarine);
  setBlock(cx - 1, 33, 9, bGold);
  setBlock(cx + 1, 33, 9, bGold);

  // Broad Shoulder Pauldrons (y = 35..36)
  for (let x = 16; x <= 18; x++) {
    for (let z = 11; z <= 13; z++) {
      setBlock(x, 35, z, bGold);
      setBlock(x, 36, z, bTitanium);
    }
  }
  for (let x = 6; x <= 8; x++) {
    for (let z = 11; z <= 13; z++) {
      setBlock(x, 35, z, bGold);
      setBlock(x, 36, z, bTitanium);
    }
  }

  // =========================================================================
  // 8. LEFT ARM & THE GREAT AEGIS HOPLON SHIELD (y = 24..35)
  // =========================================================================
  // Left upper arm
  for (let y = 32; y <= 34; y++) {
    setBlock(17, y, 12, pStone);
    setBlock(18, y, 11, pStone);
    setBlock(18, y, 12, bGold);
  }
  // Left forearm
  for (let y = 29; y <= 31; y++) {
    setBlock(18, y, 10, bGold);
    setBlock(19, y, 9, pStone);
    setBlock(19, y, 8, bGold);
  }

  // Monumental Aegis Hoplon Shield (disc centered at x = 20, y = 29, z = 7)
  const shieldCenterY = 29;
  const shieldCenterZ = 7;
  const shieldRadius = 4.6;

  for (let dy = -5; dy <= 5; dy++) {
    for (let dz = -5; dz <= 5; dz++) {
      const dist = Math.hypot(dy, dz);
      if (dist <= shieldRadius) {
        const sy = shieldCenterY + dy;
        const sz = shieldCenterZ + dz;
        const curveOffset = Math.round(-0.25 * dz);
        const sx = 20 + curveOffset;

        setBlock(sx - 1, sy, sz, bTitanium);

        if (dist <= 1.2) {
          setBlock(sx, sy, sz, bGlass);
          setBlock(sx - 1, sy, sz, bEnergy);
        } else if (dist <= 2.4) {
          const angle = Math.atan2(dy, dz);
          const isRay = Math.sin(angle * 6) > 0.2;
          setBlock(sx, sy, sz, isRay ? bGold : bPrismarine);
        } else if (dist <= 3.7) {
          setBlock(sx, sy, sz, bTitanium);
        } else {
          setBlock(sx, sy, sz, bGold);
        }
      }
    }
  }
  setBlock(18, 29, 7, bTitanium);
  setBlock(19, 29, 7, bEnergy);

  // =========================================================================
  // 9. RIGHT ARM & ENERGIZED DEFENSE SPEAR (y = 28..48)
  // =========================================================================
  // Right upper arm
  for (let y = 35; y <= 37; y++) {
    setBlock(7, y, 12, pStone);
    setBlock(6, y, 13, bGold);
    setBlock(6, y, 14, pStone);
  }
  // Right forearm
  setBlock(6, 38, 13, bGold);
  setBlock(6, 38, 12, pStone);
  setBlock(6, 37, 11, bGold);
  setBlock(6, 37, 10, pStone);
  setBlock(6, 37, 9, bGold);

  // Poised Defense Spear (From butt (7, 30, 19) to Tip (5, 47, 0))
  const spearSteps = 80;
  for (let i = 0; i <= spearSteps; i++) {
    const t = i / spearSteps;
    const px = Math.round(7 * (1 - t) + 5 * t);
    const py = Math.round(30 * (1 - t) + 47 * t);
    const pz = Math.round(19 * (1 - t) + 0 * t);

    if (t < 0.78) {
      const isPowerNode = (Math.abs(t - 0.25) < 0.03 || Math.abs(t - 0.52) < 0.03);
      if (isPowerNode) {
        setBlock(px, py, pz, bEnergy);
        setBlock(px + 1, py, pz, bGold);
      } else {
        setBlock(px, py, pz, (i % 2 === 0) ? bTitanium : bPillar);
      }
    } else {
      setBlock(px, py, pz, bEnergy);
      setBlock(px - 1, py, pz, bGlass);
      setBlock(px + 1, py, pz, bGlass);
      setBlock(px, py + 1, pz, bTitanium);
    }
  }
  // Apex lightning lance emitter at spear tip
  setBlock(5, 47, 0, bRod);
  setBlock(5, 48, 0, bEndRod);

  // =========================================================================
  // 10. NECK, HEAD & ATTIC HELMET WITH TOWERING CREST (y = 36..50)
  // =========================================================================
  // Neck (y = 36..37)
  for (let y = 36; y <= 37; y++) {
    for (let x = 11; x <= 13; x++) {
      for (let z = 11; z <= 13; z++) {
        setBlock(x, y, z, pStone);
      }
    }
  }

  // Sculpted Classical Head & Face (y = 38..41)
  for (let y = 38; y <= 41; y++) {
    for (let x = 10; x <= 14; x++) {
      for (let z = 9; z <= 13; z++) {
        setBlock(x, y, z, pStone);
      }
    }
  }
  // Face features (facing North, z = 9)
  setBlock(cx, 38, 9, bSmoothQuartz);
  setBlock(cx, 39, 9, bSmoothQuartz);
  setBlock(cx - 1, 39, 9, bEnergy);
  setBlock(cx + 1, 39, 9, bEnergy);

  // Corinthian / Attic Helmet
  for (let y = 38; y <= 40; y++) {
    setBlock(10, y, 9, bGold);
    setBlock(14, y, 9, bGold);
  }
  setBlock(cx, 40, 8, bGold);
  setBlock(cx - 1, 40, 8, bTitanium);
  setBlock(cx + 1, 40, 8, bTitanium);

  // Helmet Dome (y = 41..43)
  for (let y = 41; y <= 43; y++) {
    for (let x = 9; x <= 15; x++) {
      for (let z = 9; z <= 14; z++) {
        const d = Math.hypot((x - cx) / 2.6, (z - 11.5) / 2.3);
        if (d <= 1.05) {
          if (y === 43 || d > 0.85) setBlock(x, y, z, bGold);
          else setBlock(x, y, z, bTitanium);
        }
      }
    }
  }

  // Sweeping Classical Crest Plume (Lophos) (y = 43..50)
  for (let z = 10; z <= 13; z++) {
    setBlock(cx, 43, z, bGold);
    setBlock(cx, 44, z, bGold);
  }

  const crestProfile = [
    { y: 44, zMin: 9,  zMax: 12, w: 1 },
    { y: 45, zMin: 9,  zMax: 13, w: 1 },
    { y: 46, zMin: 10, zMax: 14, w: 1 },
    { y: 47, zMin: 10, zMax: 14, w: 1 },
    { y: 48, zMin: 11, zMax: 15, w: 1 },
    { y: 49, zMin: 11, zMax: 14, w: 0 },
    { y: 50, zMin: 12, zMax: 13, w: 0 },
    { y: 47, zMin: 15, zMax: 16, w: 0 },
    { y: 46, zMin: 15, zMax: 16, w: 0 },
    { y: 45, zMin: 15, zMax: 15, w: 0 }
  ];

  for (const seg of crestProfile) {
    for (let z = seg.zMin; z <= seg.zMax; z++) {
      for (let dx = -seg.w; dx <= seg.w; dx++) {
        const x = cx + dx;
        if (seg.y === 50 || z === seg.zMin || z === seg.zMax) {
          setBlock(x, seg.y, z, bGold);
        } else if (dx === 0) {
          setBlock(x, seg.y, z, bPrismarine);
        } else {
          setBlock(x, seg.y, z, bSmoothQuartz);
        }
      }
    }
  }

  // =========================================================================
  // 11. RETURN STRUCTURE METADATA
  // =========================================================================
  return {
    name: "guardian_colossus",
    seatY: seatY,
    anchors: {
      front: [12, 4, 0],
      door: [12, 5, 2]
    },
    interiors: [
      {
        min: [7, 5, 7],
        max: [17, 10, 17],
        kind: "vault"
      }
    ]
  };
}

amphibious_beast.source:
export const envelope = [15, 14, 17];

export default function build(api) {
  const [W, H, D] = api.size;
  const seatY = 3;

  // Grid buffer for envelope-confined deterministic voxel placement
  const grid = Array.from({ length: W }, () =>
    Array.from({ length: H }, () =>
      new Array(D).fill(null)
    )
  );

  function setBlock(x, y, z, block) {
    const ix = Math.round(x);
    const iy = Math.round(y);
    const iz = Math.round(z);
    if (ix >= 0 && ix < W && iy >= 0 && iy < H && iz >= 0 && iz < D) {
      grid[ix][iy][iz] = block;
    }
  }

  function fillEllipsoid(cx, cy, cz, rx, ry, rz, block) {
    const minX = Math.max(0, Math.floor(cx - rx));
    const maxX = Math.min(W - 1, Math.ceil(cx + rx));
    const minY = Math.max(0, Math.floor(cy - ry));
    const maxY = Math.min(H - 1, Math.ceil(cy + ry));
    const minZ = Math.max(0, Math.floor(cz - rz));
    const maxZ = Math.min(D - 1, Math.ceil(cz + rz));

    for (let x = minX; x <= maxX; x++) {
      const dx = (x - cx) / rx;
      for (let y = minY; y <= maxY; y++) {
        const dy = (y - cy) / ry;
        for (let z = minZ; z <= maxZ; z++) {
          const dz = (z - cz) / rz;
          if (dx * dx + dy * dy + dz * dz <= 1.0) {
            grid[x][y][z] = typeof block === "function" ? block(x, y, z) : block;
          }
        }
      }
    }
  }

  function drawCapsule(p1, p2, radius, block) {
    const [x1, y1, z1] = p1;
    const [x2, y2, z2] = p2;
    const dist = Math.hypot(x2 - x1, y2 - y1, z2 - z1);
    const steps = Math.max(1, Math.ceil(dist * 2.5));
    for (let s = 0; s <= steps; s++) {
      const t = s / steps;
      const px = x1 + (x2 - x1) * t;
      const py = y1 + (y2 - y1) * t;
      const pz = z1 + (z2 - z1) * t;
      fillEllipsoid(px, py, pz, radius, radius, radius, block);
    }
  }

  function plantFoot(footCenterX, footCenterZ, footY, radiusX, radiusZ, talonBlock, clawBlock) {
    // Fill foot pad downwards to ground
    const minX = Math.floor(footCenterX - radiusX);
    const maxX = Math.ceil(footCenterX + radiusX);
    const minZ = Math.floor(footCenterZ - radiusZ);
    const maxZ = Math.ceil(footCenterZ + radiusZ);

    for (let x = minX; x <= maxX; x++) {
      for (let z = minZ; z <= maxZ; z++) {
        const dx = (x - footCenterX) / radiusX;
        const dz = (z - footCenterZ) / radiusZ;
        if (dx * dx + dz * dz <= 1.0) {
          const terrainY = Math.max(0, Math.min(seatY + 2, seatY + Math.round(api.heightAt(x, z))));
          const topY = Math.round(footY);
          const bottomY = Math.min(terrainY, seatY);
          for (let y = topY; y >= bottomY; y--) {
            if (y >= 0 && y < H && x >= 0 && x < W && z >= 0 && z < D) {
              grid[x][y][z] = talonBlock;
            }
          }
        }
      }
    }

    // Webbed claw talons extending forward/downward
    const clawAngles = [-0.55, 0.0, 0.55];
    for (const angle of clawAngles) {
      const clawLen = 2;
      const clawDirX = Math.sin(angle) * (footCenterX < 7 ? -1 : 1);
      const clawDirZ = -Math.cos(angle);
      for (let c = 1; c <= clawLen; c++) {
        const cx = Math.round(footCenterX + clawDirX * c);
        const cz = Math.round(footCenterZ + clawDirZ * c);
        const cy = Math.round(footY - (c * 0.4));
        if (cx >= 0 && cx < W && cy >= 0 && cy < H && cz >= 0 && cz < D) {
          grid[cx][cy][cz] = clawBlock;
          const clawGround = Math.max(0, Math.min(seatY + 1, seatY + Math.round(api.heightAt(cx, cz))));
          for (let y = cy - 1; y >= clawGround; y--) {
            if (y >= 0 && y < H) grid[cx][y][cz] = clawBlock;
          }
        }
      }
    }
  }

  // Four thematic bio-material palettes
  const PALETTES = [
    {
      shellPrimary: "minecraft:dark_prismarine",
      shellSecondary: "minecraft:deepslate_tiles",
      bellyPrimary: "minecraft:prismarine_bricks",
      bellySecondary: "minecraft:prismarine",
      glowOrgan: "minecraft:sea_lantern",
      accentGlow: "minecraft:crying_obsidian",
      boneTooth: "minecraft:bone_block[axis=y]",
      clawBlock: "minecraft:deepslate_bricks",
      eyeBlock: "minecraft:sea_lantern",
    },
    {
      shellPrimary: "minecraft:dark_prismarine",
      shellSecondary: "minecraft:warped_wart_block",
      bellyPrimary: "minecraft:prismarine",
      bellySecondary: "minecraft:prismarine_bricks",
      glowOrgan: "minecraft:verdant_froglight",
      accentGlow: "minecraft:crying_obsidian",
      boneTooth: "minecraft:bone_block[axis=y]",
      clawBlock: "minecraft:dark_prismarine",
      eyeBlock: "minecraft:verdant_froglight",
    },
    {
      shellPrimary: "minecraft:polished_deepslate",
      shellSecondary: "minecraft:dark_prismarine",
      bellyPrimary: "minecraft:deepslate_bricks",
      bellySecondary: "minecraft:prismarine_bricks",
      glowOrgan: "minecraft:ochre_froglight",
      accentGlow: "minecraft:crying_obsidian",
      boneTooth: "minecraft:bone_block[axis=y]",
      clawBlock: "minecraft:bone_block[axis=y]",
      eyeBlock: "minecraft:ochre_froglight",
    },
    {
      shellPrimary: "minecraft:dark_prismarine",
      shellSecondary: "minecraft:moss_block",
      bellyPrimary: "minecraft:prismarine_bricks",
      bellySecondary: "minecraft:dark_prismarine",
      glowOrgan: "minecraft:sea_lantern",
      accentGlow: "minecraft:prismarine",
      boneTooth: "minecraft:bone_block[axis=y]",
      clawBlock: "minecraft:dark_prismarine",
      eyeBlock: "minecraft:sea_lantern",
    },
  ];

  const instIdx = api.instance.index;
  const palIdx = (instIdx + Math.floor(api.random() * 4)) % PALETTES.length;
  const pal = PALETTES[palIdx];

  const mawStyle = instIdx % 3; // 0: Roaring Maw, 1: Angler Lure, 2: Mandible Pincers
  const spineStyle = Math.floor(instIdx / 2) % 3; // 0: Fin Sail, 1: Double Spikes, 2: Heavy Scutes
  const hexapod = instIdx % 4 === 2; // Extra middle limbs
  const tailStyle = instIdx % 3; // 0: Caudal Fin, 1: Stinger Arch, 2: Spiked Club

  const coreX = 7;
  const coreY = seatY + 3.5;
  const spineCurveX = (api.random() - 0.5) * 1.4;
  const spineCurveY = (api.random() - 0.5) * 0.6;
  const headTurnX = (api.random() - 0.5) * 1.6;
  const headTiltY = (api.random() - 0.5) * 0.8;
  const tailSwayX = (api.random() - 0.5) * 3.0;
  const tailRiseY = api.random() * 2.2;

  // 1. MAIN TORSO & CARAPACE (z: 4 to 12)
  for (let z = 4; z <= 12; z++) {
    const t = (z - 4) / 8;
    const bx = coreX + spineCurveX * Math.sin(t * Math.PI);
    const by = coreY + spineCurveY * Math.cos(t * Math.PI * 0.8);

    let rx, ry;
    if (z <= 5) {
      rx = 2.4 + (z - 4) * 0.6;
      ry = 2.0 + (z - 4) * 0.4;
    } else if (z <= 9) {
      rx = 3.6 + Math.sin(((z - 6) / 3) * Math.PI) * 0.6;
      ry = 2.6 + Math.sin(((z - 6) / 3) * Math.PI) * 0.4;
    } else {
      rx = 3.6 - (z - 9) * 0.5;
      ry = 2.7 - (z - 9) * 0.3;
    }

    for (let x = Math.floor(bx - rx); x <= Math.ceil(bx + rx); x++) {
      const dx = (x - bx) / rx;
      for (let y = Math.floor(by - ry); y <= Math.ceil(by + ry); y++) {
        const dy = (y - by) / ry;
        const distSq = dx * dx + dy * dy;
        if (distSq <= 1.0) {
          let block;
          if (distSq < 0.28 && y < by + 0.4) {
            block = pal.glowOrgan; // Bioluminescent internal core
          } else if (y < by - 0.2) {
            block = Math.abs(dx) > 0.65 ? pal.bellySecondary : pal.bellyPrimary;
          } else {
            if (Math.abs(dx) < 0.25) {
              block = pal.shellPrimary;
            } else if (distSq > 0.75 && api.random() < 0.18) {
              block = pal.accentGlow;
            } else {
              block = (x + y + z) % 2 === 0 ? pal.shellPrimary : pal.shellSecondary;
            }
          }
          setBlock(x, y, z, block);
        }
      }
    }

    // Breathing bioluminescent gill vents
    if (z >= 6 && z <= 8) {
      setBlock(Math.floor(bx - rx), Math.round(by), z, pal.glowOrgan);
      setBlock(Math.ceil(bx + rx), Math.round(by), z, pal.glowOrgan);
    }
  }

  // 2. HEAD & MAW (z: 1 to 4)
  const headX = coreX + headTurnX;
  const headY = coreY + headTiltY;

  if (mawStyle === 0) {
    // Wide Roaring Maw with glowing gullet & sharp teeth
    fillEllipsoid(headX, headY + 0.8, 2.5, 2.0, 1.3, 1.8, (x, y) => {
      if (y >= headY + 1.2 && Math.abs(x - headX) < 0.6) return pal.shellPrimary;
      return pal.shellSecondary;
    });
    for (let x = Math.floor(headX - 1.5); x <= Math.ceil(headX + 1.5); x++) {
      setBlock(x, Math.round(headY + 0.2), 1, pal.boneTooth);
    }
    fillEllipsoid(headX, headY - 1.4, 2.2, 1.6, 0.8, 1.6, pal.shellPrimary);
    for (let x = Math.floor(headX - 1.2); x <= Math.ceil(headX + 1.2); x++) {
      setBlock(x, Math.round(headY - 0.8), 1, pal.boneTooth);
    }
    fillEllipsoid(headX, headY - 0.3, 2.8, 1.0, 0.9, 1.2, pal.glowOrgan);
    setBlock(headX - 1.8, headY + 1.2, 3, pal.eyeBlock);
    setBlock(headX + 1.8, headY + 1.2, 3, pal.eyeBlock);
  } else if (mawStyle === 1) {
    // Angler Lure Snout
    fillEllipsoid(headX, headY, 2.2, 1.8, 1.5, 2.0, pal.shellPrimary);
    for (let z = 1; z <= 2; z++) {
      setBlock(headX - 1.4, headY - 0.2, z, pal.boneTooth);
      setBlock(headX + 1.4, headY - 0.2, z, pal.boneTooth);
    }
    setBlock(headX - 1.7, headY + 1.0, 3, pal.eyeBlock);
    setBlock(headX + 1.7, headY + 1.0, 3, pal.eyeBlock);
    // Bioluminescent stalk and dangling lure
    setBlock(headX, headY + 1.8, 3, pal.boneTooth);
    setBlock(headX, headY + 2.5, 2, pal.boneTooth);
    setBlock(headX, headY + 2.8, 1, pal.boneTooth);
    setBlock(headX, headY + 2.2, 0, pal.glowOrgan);
    setBlock(headX, headY + 1.6, 0, pal.accentGlow);
  } else {
    // Mandible Pincer Maw
    fillEllipsoid(headX, headY, 2.5, 1.6, 1.4, 1.8, pal.shellPrimary);
    setBlock(headX, headY, 1, pal.boneTooth);
    setBlock(headX, headY - 0.8, 1, pal.boneTooth);
    drawCapsule([headX - 1.8, headY, 3.0], [headX - 2.6, headY, 1.5], 0.8, pal.shellSecondary);
    drawCapsule([headX - 2.6, headY, 1.5], [headX - 1.2, headY, 0.8], 0.6, pal.boneTooth);
    drawCapsule([headX + 1.8, headY, 3.0], [headX + 2.6, headY, 1.5], 0.8, pal.shellSecondary);
    drawCapsule([headX + 2.6, headY, 1.5], [headX + 1.2, headY, 0.8], 0.6, pal.boneTooth);
    setBlock(headX - 0.8, headY + 0.8, 2, pal.eyeBlock);
    setBlock(headX + 0.8, headY + 0.8, 2, pal.eyeBlock);
    setBlock(headX, headY + 1.2, 2.5, pal.eyeBlock);
  }

  // 3. DORSAL CREST & CARAPACE SPINES
  if (spineStyle === 0) {
    // High Fin Sail
    for (let z = 4; z <= 12; z++) {
      const finH = Math.sin(((z - 4) / 8) * Math.PI) * 3.6;
      const baseY = coreY + 2.0;
      for (let y = Math.floor(baseY); y <= Math.ceil(baseY + finH); y++) {
        if (y === Math.ceil(baseY + finH)) {
          setBlock(coreX, y, z, pal.shellPrimary);
        } else if ((z + y) % 2 === 0) {
          setBlock(coreX, y, z, pal.glowOrgan);
        } else {
          setBlock(coreX, y, z, pal.shellSecondary);
        }
      }
    }
  } else if (spineStyle === 1) {
    // Double Row of Curved Bone Horns
    const spikeZ = [4, 6, 8, 10, 12];
    for (const sz of spikeZ) {
      const spikeH = 2 + Math.floor(Math.sin(((sz - 4) / 8) * Math.PI) * 2.2);
      const baseY = Math.round(coreY + 2.2);
      for (let h = 0; h <= spikeH; h++) {
        setBlock(coreX - 1.6, baseY + h, sz + (h > 1 ? 1 : 0), pal.boneTooth);
        setBlock(coreX + 1.6, baseY + h, sz + (h > 1 ? 1 : 0), pal.boneTooth);
      }
    }
  } else {
    // Armored Carapace Nodes & Shell Scutes
    for (let z = 4; z <= 12; z += 2) {
      const baseY = Math.round(coreY + 2.4);
      fillEllipsoid(coreX, baseY, z, 1.8, 1.0, 1.0, pal.shellPrimary);
      setBlock(coreX, baseY + 1, z, pal.glowOrgan);
      setBlock(coreX - 1.8, baseY, z, pal.accentGlow);
      setBlock(coreX + 1.8, baseY, z, pal.accentGlow);
    }
  }

  // 4. TAIL & POSTERIOR APPENDAGES (z: 12 to 16)
  for (let z = 12; z <= 16; z++) {
    const t = (z - 12) / 4;
    const tx = coreX + tailSwayX * t * t;
    const ty = coreY - 0.5 + tailRiseY * t;
    const r = 2.2 * (1.0 - t * 0.7);
    fillEllipsoid(tx, ty, z, r, r * 0.85, 1.0, (x, y) => {
      if (y >= ty) return pal.shellPrimary;
      return pal.bellyPrimary;
    });
  }

  const tipX = coreX + tailSwayX;
  const tipY = coreY - 0.5 + tailRiseY;
  if (tailStyle === 0) {
    // Caudal Shark Fluke
    for (let fy = Math.floor(tipY - 2.2); fy <= Math.ceil(tipY + 2.5); fy++) {
      setBlock(tipX, fy, 15, pal.shellPrimary);
      setBlock(tipX, fy, 16, pal.shellSecondary);
    }
    setBlock(tipX, Math.round(tipY), 16, pal.glowOrgan);
  } else if (tailStyle === 1) {
    // Scorpion Stinger Arch
    setBlock(tipX, tipY + 1.5, 15, pal.boneTooth);
    setBlock(tipX, tipY + 2.2, 14, pal.boneTooth);
    setBlock(tipX, tipY + 2.8, 13, pal.boneTooth);
    setBlock(tipX, tipY + 2.2, 13, pal.glowOrgan);
  } else {
    // Spiked Tail Club
    fillEllipsoid(tipX, tipY, 15.5, 1.6, 1.2, 1.2, pal.shellPrimary);
    setBlock(tipX - 1.8, tipY, 15, pal.boneTooth);
    setBlock(tipX + 1.8, tipY, 15, pal.boneTooth);
    setBlock(tipX, tipY + 1.5, 15, pal.boneTooth);
    setBlock(tipX, tipY - 1.2, 15, pal.boneTooth);
  }

  // 5. LIMBS & WEBBED TALONS
  const legOffset1 = (api.random() - 0.5) * 1.2;
  const legOffset2 = (api.random() - 0.5) * 1.2;

  // Front Left Leg
  drawCapsule([coreX - 3.2, coreY + 0.2, 5.5], [coreX - 4.8, coreY - 0.5, 4.5 + legOffset1], 1.2, pal.shellPrimary);
  drawCapsule([coreX - 4.8, coreY - 0.5, 4.5 + legOffset1], [coreX - 4.2, seatY + 1.2, 3.2 + legOffset1], 1.0, pal.shellSecondary);
  plantFoot(coreX - 4.2, 3.0 + legOffset1, seatY + 0.8, 1.4, 1.4, pal.shellPrimary, pal.clawBlock);

  // Front Right Leg
  drawCapsule([coreX + 3.2, coreY + 0.2, 5.5], [coreX + 4.8, coreY - 0.5, 4.5 + legOffset2], 1.2, pal.shellPrimary);
  drawCapsule([coreX + 4.8, coreY - 0.5, 4.5 + legOffset2], [coreX + 4.2, seatY + 1.2, 3.2 + legOffset2], 1.0, pal.shellSecondary);
  plantFoot(coreX + 4.2, 3.0 + legOffset2, seatY + 0.8, 1.4, 1.4, pal.shellPrimary, pal.clawBlock);

  // Rear Left Leg
  drawCapsule([coreX - 2.8, coreY - 0.2, 10.5], [coreX - 4.6, coreY - 0.6, 11.8], 1.3, pal.shellPrimary);
  drawCapsule([coreX - 4.6, coreY - 0.6, 11.8], [coreX - 4.0, seatY + 1.2, 12.5], 1.0, pal.shellSecondary);
  plantFoot(coreX - 4.0, 13.0, seatY + 0.8, 1.4, 1.4, pal.shellPrimary, pal.clawBlock);

  // Rear Right Leg
  drawCapsule([coreX + 2.8, coreY - 0.2, 10.5], [coreX + 4.6, coreY - 0.6, 11.8], 1.3, pal.shellPrimary);
  drawCapsule([coreX + 4.6, coreY - 0.6, 11.8], [coreX + 4.0, seatY + 1.2, 12.5], 1.0, pal.shellSecondary);
  plantFoot(coreX + 4.0, 13.0, seatY + 0.8, 1.4, 1.4, pal.shellPrimary, pal.clawBlock);

  // Optional Middle Pair of Limbs for Hexapod variant
  if (hexapod) {
    drawCapsule([coreX - 3.4, coreY - 0.2, 8.0], [coreX - 5.0, coreY - 0.8, 8.0], 1.0, pal.shellPrimary);
    plantFoot(coreX - 4.6, 8.0, seatY + 0.8, 1.2, 1.2, pal.shellPrimary, pal.clawBlock);
    drawCapsule([coreX + 3.4, coreY - 0.2, 8.0], [coreX + 5.0, coreY - 0.8, 8.0], 1.0, pal.shellPrimary);
    plantFoot(coreX + 4.6, 8.0, seatY + 0.8, 1.2, 1.2, pal.shellPrimary, pal.clawBlock);
  }

  // 6. CONNECTIVITY ENFORCEMENT (Rule 9: Single 6-connected solid)
  const visited = Array.from({ length: W }, () =>
    Array.from({ length: H }, () =>
      new Uint8Array(D)
    )
  );

  const components = [];
  for (let x = 0; x < W; x++) {
    for (let y = 0; y < H; y++) {
      for (let z = 0; z < D; z++) {
        if (grid[x][y][z] && !visited[x][y][z]) {
          const comp = [];
          const queue = [[x, y, z]];
          visited[x][y][z] = 1;
          let head = 0;
          while (head < queue.length) {
            const [cx, cy, cz] = queue[head++];
            comp.push([cx, cy, cz]);
            const neighbors = [
              [cx + 1, cy, cz],
              [cx - 1, cy, cz],
              [cx, cy + 1, cz],
              [cx, cy - 1, cz],
              [cx, cy, cz + 1],
              [cx, cy, cz - 1],
            ];
            for (const [nx, ny, nz] of neighbors) {
              if (
                nx >= 0 && nx < W &&
                ny >= 0 && ny < H &&
                nz >= 0 && nz < D &&
                grid[nx][ny][nz] &&
                !visited[nx][ny][nz]
              ) {
                visited[nx][ny][nz] = 1;
                queue.push([nx, ny, nz]);
              }
            }
          }
          components.push(comp);
        }
      }
    }
  }

  if (components.length > 0) {
    components.sort((a, b) => b.length - a.length);
    const mainComp = components[0];
    const mainSet = new Set(mainComp.map(([x, y, z]) => (x << 16) | (y << 8) | z));
    for (let x = 0; x < W; x++) {
      for (let y = 0; y < H; y++) {
        for (let z = 0; z < D; z++) {
          if (grid[x][y][z] && !mainSet.has((x << 16) | (y << 8) | z)) {
            grid[x][y][z] = null;
          }
        }
      }
    }
  }

  // 7. EMIT BLOCKS
  for (let x = 0; x < W; x++) {
    for (let y = 0; y < H; y++) {
      for (let z = 0; z < D; z++) {
        const block = grid[x][y][z];
        if (block) {
          api.set(x, y, z, block);
        }
      }
    }
  }

  return {
    name: "amphibious_beast",
    seatY: seatY,
    anchors: {
      front: [7, seatY + 2, 0],
    },
  };
}
